  ["COMIC_11_2_KR5_KR5"] = "...như thể nó đang theo dõi chúng ta...",

  ["COMIC_11_2_KR6_KR6"] = "...CỦA TÔI!!!",

  ["COMIC_11_3_KR5_KR5"] = "...tiến lên và ẩn nấp...",

  ["COMIC_11_3_KR6_KR6"] = "HOÀNG TỬ, BÂY GIỜ CHÚNG TA LÀM GÌ?",

  ["COMIC_11_4_KR5_KR5"] = "...sẵn sàng nuốt chửng chúng ta.",

  ["COMIC_11_4_KR6_KR6"] = "ĐỪNG LO LẮNG, LÍNH.",

  ["COMIC_11_5_KR5_KR5"] = "Hãy cẩn thận!",

  ["COMIC_11_5_KR6_KR6"] = "TÔI SẼ LÀM ĐIỀU ĐÚNG.",

  ["COMIC_11_6_KR5_KR5"] = "Chúng ta đang bị tấn công!",

  ["COMIC_11_6_KR6_KR6"] = "KHÔNG... KHÔNG THỂ ĐƯỢC!",

  ["COMIC_11_7_KR5_KR5"] = "Đi đi, cô bé nhỏ! Sự an toàn của chúng tôi nằm ở sự vội vàng của bạn!",

  ["COMIC_11_7_KR6_KR6"] = "VUA ĐAN...",

  ["COMIC_11_8_KR6_KR6"] = "CHÚNG TÔI ĐÃ LÀM GÌ?!",

  ["COMIC_11_9_KR6_KR6"] = "Còn tiếp...",

  ["COMIC_12_1_KR5_KR5"] = "Đơn giản chỉ cần nhốt bạn là một sai lầm. Một điều tôi sẽ không lặp lại.",

  ["COMIC_12_1_KR6_KR6"] = "TÔI SẼ LÀM GÌ BÂY GIỜ...?",

  ["COMIC_12_2_KR5_KR5"] = "KHÔNG!!!",

  ["COMIC_12_2_KR6_KR6"] = "CUỐI CÙNG BẠN ĐANG Ở ĐÂY, LIGHTSEEKER.",

  ["COMIC_12_3_KR5_KR5"] = "Ta trục xuất ngươi mãi mãi!!",

  ["COMIC_12_3_KR6_KR6"] = "ALERIA?!",

  ["COMIC_12_4_KR5_KR5"] = "Ho!",

  ["COMIC_12_4_KR6_KR6"] = "LÀM ƠN, NÓI CHO TÔI ĐIỀU GÌ ĐANG XẢY RA!",

  ["COMIC_12_5_KR5_KR5"] = "Khụ, khụ!",

  ["COMIC_12_5_KR6_KR6"] = "TÔI SẼ GIẢI THÍCH TRONG THỜI GIAN ĐÚNG.",

  ["COMIC_12_6_KR5_KR5"] = "Uh... chắc là tôi đã nghỉ tập rồi.",

  ["COMIC_12_6_KR6_KR6"] = "CHÚNG TA PHẢI NHANH CHÓNG NGAY BÂY GIỜ.",

  ["COMIC_12_7_KR6_KR6"] = "TÔI KHÔNG PHẢI LÀ NGƯỜI DUY NHẤT CHỜ BẠN ĐẾN.",

  ["COMIC_13_1_KR5_KR5"] = "Họ nói đó là sự điên rồ.",

  ["COMIC_13_2_KR5_KR5"] = "Rằng một vũ khí như vậy là không thể.",

  ["COMIC_13_3_KR5_KR5"] = "Nhưng chẳng bao lâu nữa họ sẽ biết mình đã sai lầm như thế nào...",

  ["COMIC_13_4_KR5_KR5"] = "...và đầu hàng trước thiên tài của Grymbeard!",

  ["COMIC_14_1_KR5_KR5"] = "Chúng ta sẽ làm gì với chúng?",

  ["COMIC_14_2_KR5_KR5"] = "Để chúng cho tôi!",

  ["COMIC_14_3_KR5_KR5"] = "Tôi chỉ biết chỗ đó thôi.",

  ["COMIC_14_4_KR5_KR5"] = "Vậy đây là nó à?",

  ["COMIC_14_5_KR5_KR5"] = "Làm cho Grymbeard thối rữa trong phòng giam?!",

  ["COMIC_14_6_KR5_KR5"] = "Hoàn toàn ngược lại, người bạn lùn của tôi...",

  ["COMIC_14_7_KR5_KR5"] = "...Tôi có kế hoạch lớn cho bộ não to lớn của bạn!",

  ["COMIC_15_10_KR5_KR5"] = "...nhưng không ở trong tình trạng tốt.",

  ["COMIC_15_1_KR5_KR5"] = "Ở một nơi nào đó trên núi.",

  ["COMIC_15_2_KR5_KR5"] = "Này, yêu tinh!",

  ["COMIC_15_3_KR5_KR5"] = "Hãy bắt tay vào làm việc!",

  ["COMIC_15_4_KR5_KR5"] = "Bạn cần phải gửi một tin nhắn.",

  ["COMIC_15_5_KR5_KR5"] = "Chúng ta nên gửi thêm trinh sát. Chúng ta không thể yên tâm khi có tất cả những kẻ sùng đạo lang thang khắp nơi.",

  ["COMIC_15_6_KR5_KR5"] = "Chúng ta có thể cử một số người đến giúp đỡ; họ...",

  ["COMIC_15_7_KR5_KR5"] = "Chúa tể bóng tối! Tin khẩn cấp!",

  ["COMIC_15_8_KR5_KR5"] = "Tốt...",

  ["COMIC_15_9_KR5_KR5"] = "Chúng tôi đã tìm thấy trinh sát của mình...",

  ["COMIC_16_1_KR5_KR5"] = "Tôi sẽ được trả thù!",

  ["COMIC_16_2_KR5_KR5"] = "Em gái tôi... sao vậy?",

  ["COMIC_17_10_KR5_KR5"] = "Nếu chúng ta không ngăn chặn chúng, chúng sẽ quét sạch tất cả các vương quốc!",

  ["COMIC_17_11_KR5_KR5"] = "Chúng ta phải giúp anh ấy!",

  ["COMIC_17_12_KR5_KR5"] = "Ồ, chắc chắn là có.",

  ["COMIC_17_13_KR5_KR5"] = "Chắc chắn chúng tôi làm...",

  ["COMIC_17_1_KR5_KR5"] = "Buổi chiều đẹp trời phải không?",

  ["COMIC_17_2_KR5_KR5"] = "Tôi có thể quen với sự bình yên này.",

  ["COMIC_17_3_KR5_KR5"] = "Tốt hơn là không.",

  ["COMIC_17_4_KR5_KR5"] = "Sun, cậu đấy à?! Bạn có thể chỉ cần vẫy tay, bạn biết đấy...",

  ["COMIC_17_5_KR5_KR5"] = "Các bạn ơi, có điều gì đó khủng khiếp đã xảy ra...",

  ["COMIC_17_6_KR5_KR5"] = "Tôi đang yên bình thiền định về con rùa của mình thì...",

  ["COMIC_17_7_KR5_KR5"] = "Ba vị vua quỷ đột nhiên xuất hiện!",

  ["COMIC_17_8_KR5_KR5"] = "Không cần phải nói, tôi đã chiến đấu anh dũng, nhưng...",

  ["COMIC_17_9_KR5_KR5"] = "Họ đã lấy đi những thiên cầu mà tôi đang bảo vệ!",

  ["COMIC_18_1_KR5_KR5"] = "Gần bờ hang ổ của Bull Demon King...",

  ["COMIC_18_2_KR5_KR5"] = "Đã phát hiện mục tiêu!",

  ["COMIC_18_3_KR5_KR5"] = "Hãy cho nổ tung pháo đài đó!",

  ["COMIC_18_4_KR5_KR5"] = "Những bức tường của tôi cười nhạo những viên sỏi của bạn!",

  ["COMIC_18_5_KR5_KR5"] = "Vì Linirea!",

  ["COMIC_18_6_KR5_KR5"] = "Lùi lại đi các chàng trai! Chúng tôi cần một sự mở đầu ở đây!",

  ["COMIC_19_1_KR5_KR5"] = "Các thiên cầu không thể được bạn quản lý, thật vô lý!",

  ["COMIC_19_2_KR5_KR5"] = "Vâng, hãy cẩn thận với điều đó, anh bạn.",

  ["COMIC_19_3_KR5_KR5"] = "Bạn đã rất khôn ngoan, con khỉ cao quý!",

  ["COMIC_19_4_KR5_KR5"] = "Tôi sẽ làm gì với ba người đây?",

  ["COMIC_1_10_KR6_KR6"] = "NHƯNG CHÚNG TA VẪN CÓ CƠ HỘI.",

  ["COMIC_1_11_KR6_KR6"] = "TÔI SẼ CHIẾN ĐẤU ĐỂ CÓ MỘT NGÀY MAI TỐT HƠN!",

  ["COMIC_1_1_KR3"] = "Mọi chuyện bắt đầu từ rất lâu rồi ở một vùng đất xa xôi…",

  ["COMIC_1_1_KR5"] = "Đã một tháng kể từ khi chúng tôi đến vùng đất này để tìm kiếm vị Vua đã mất của mình...",

  ["COMIC_1_1_KR6_KR6"] = "CHÚNG TÔI QUÁ NGÂY HY VỌNG RẰNG HÒA BÌNH SẼ KÉO DÀI LÂU VÀ RẰNG NGƯỜI ĐIÊN CÓ THỂ TIN TƯỞNG.",

  ["COMIC_1_2B_KR5"] = "...Sau khi bị trục xuất bởi Vez'nan, Bruxa hắc ám.",

  ["COMIC_1_2_KR3"] = "… nơi mọi người sống trong hòa bình.",

  ["COMIC_1_2_KR6_KR6"] = "TÔI... KHÔNG THỂ CHỊU ĐƯỢC... LÂU HƠN NỮA!",

  ["COMIC_1_3_KR2"] = "Cái búa!",

  ["COMIC_1_3_KR6_KR6"] = "GERALD, ĐẾN LÚC NÀY.",

  ["COMIC_1_4_KR2"] = "Nó sẽ không giữ được lâu nữa! Phía đông sắp sụp đổ!",

  ["COMIC_1_4_KR5"] = "Chúng tôi tìm một nơi và dựng trại để hồi phục sức lực...",

  ["COMIC_1_4_KR6_KR6"] = "BẠN CÓ CHẮC CHẮN KHÔNG?",

  ["COMIC_1_5_KR2"] = "Chaaaarge!!",

  ["COMIC_1_5_KR3"] = "nhưng khi câu chuyện diễn ra…",

  ["COMIC_1_5_KR5"] = "...trong hòa bình...",

  ["COMIC_1_5_KR6_KR6"] = "CHÚNG TÔI PHẢI THỬ.",

  ["COMIC_1_6_KR3"] = "… hòa bình không bao giờ tồn tại mãi mãi!",

  ["COMIC_1_6_KR6_KR6"] = "THANH KIẾM NÀY LÀ TẤT CẢ MỌI NGƯỜI MUỐN.",

  ["COMIC_1_7_KR6_KR6"] = "NGAY BÂY GIỜ ĐI, BẠN CŨ!",

  ["COMIC_1_8_KR5"] = "...Nhưng có vẻ như chuyện đó đã kết thúc rồi.",

  ["COMIC_1_8_KR6_KR6"] = "CHÚNG TÔI BỎ NGƯỜI BẢO VỆ CỦA CHÚNG TÔI XUỐNG VÀ CHÚNG TÔI TRẢ GIÁ CAO",

  ["COMIC_1_9_KR6_KR6"] = "HÀ, HÀ, HÀ!",

  ["COMIC_20_10_KR5_KR5"] = "Chúng dường như được tạo ra bởi máu rồng bị hư hỏng!",

  ["COMIC_20_11_KR5_KR5"] = "Làm thế nào tôi không nghĩ đến điều đó?",

  ["COMIC_20_1_KR5_KR5"] = "Sau đó, tại Cổng Rồng.",

  ["COMIC_20_2_KR5_KR5"] = "Điều này trông giống như Draconian cũ ...",

  ["COMIC_20_3_KR5_KR5"] = "Tôi là Aurion, người bảo vệ Vương quốc Mây.",

  ["COMIC_20_4_KR5_KR5"] = "Tôi mang đến những tin tức khủng khiếp!",

  ["COMIC_20_5_KR5_KR5"] = "Lunaris cần sự giúp đỡ của chúng ta để bảo vệ Thánh địa Trứng của Nữ hoàng Rồng.",

  ["COMIC_20_6_KR5_KR5"] = "Ôi trời...!",

  ["COMIC_20_7_KR5_KR5"] = "Liên minh sẽ trả lời cuộc gọi.",

  ["COMIC_20_8_KR5_KR5"] = "Ừm...",

  ["COMIC_20_9_KR5_KR5"] = "Vez'nan, mang người của chúng tôi tới!",

  ["COMIC_21_1_KR5_KR5"] = "Cảnh giác!",

  ["COMIC_21_2_KR5_KR5"] = "Bảo vệ thánh địa!",

  ["COMIC_21_3_KR5_KR5"] = "Đây là chỗ đứng cuối cùng của chúng tôi!",

  ["COMIC_21_4_KR5_KR5"] = "Chiếc khiên sẽ không tồn tại được lâu nữa...",

  ["COMIC_21_5_KR5_KR5"] = "Chúng ta cần Aurion!",

  ["COMIC_21_6_KR5_KR5"] = "Ha ha ha! Điều này dễ dàng hơn mong đợi.",

  ["COMIC_22_1_KR5_KR5"] = "Chẳng bao lâu nữa tôi sẽ trở thành Vua Rồng! Hà Hà Hà!",

  ["COMIC_22_2_KR5_KR5"] = "Đội quân drak của tôi đâu?",

  ["COMIC_22_3_KR5_KR5"] = "Drakmother lười biếng. Tôi có phải tự mình làm tất cả không?",

  ["COMIC_22_4_KR5_KR5"] = "Chúng ta cần thông báo cho các vị vua...",

  ["COMIC_22_5_KR5_KR5"] = "Trứng có thể được phục hồi ngay bây giờ!",

  ["COMIC_23_1_KR5_KR5"] = "Chúng tôi đã làm được!",

  ["COMIC_23_2_KR5_KR5"] = "Trứng đã được phục hồi!",

  ["COMIC_2_10_KR6_KR6"] = "HIỂN THỊ NÓ CHO CÁC ĐỒNG MINH CỦA CHÚNG TÔI ĐỂ THAM GIA VỚI BẠN TRONG SỨ MỆNH CỦA BẠN.",

  ["COMIC_2_11_KR6_KR6"] = "CẢM ƠN BẠN, VUA TUYỆT VỜI.",

  ["COMIC_2_12_KR6_KR6"] = "THÔNG BÁO CHO CON TRAI CỦA TÔI. HIỆN NAY.",

  ["COMIC_2_1_1_KR2"] = "Bạn có chắc con lạch ở quanh đây không?",

  ["COMIC_2_1_2_KR2"] = "khẳng định",

  ["COMIC_2_1_KR3"] = "Và thế là công chúa Elf bay đến vương quốc Linirea để tìm kiếm sự giúp đỡ…",

  ["COMIC_2_1_KR5"] = "HURRAH!!",

  ["COMIC_2_1_KR6_KR6"] = "CẢM ƠN SỰ GIÚP ĐỠ, NGƯỜI LÍNH BRAVE! CHÚNG TÔI CÓ THỂ TRẢ LẠI CHO BẠN NHƯ THẾ NÀO?",

  ["COMIC_2_2_1_KR2"] = "Hãy nhanh lên. Tôi muốn quay trở lại trại.",

  ["COMIC_2_2_1_KR3"] = "…trong lúc đội quân yêu tinh lùi vào Rừng Tiên…",

  ["COMIC_2_2_2_KR2"] = "Có gì vội thế?",

  ["COMIC_2_2_2_KR3"] = "Chúng ta hãy tìm một nơi an toàn!",

  ["COMIC_2_2_KR6_KR6"] = "Bệ hạ, Bệ hạ CẦN LƯU Ý LỜI CỦA TÔI!",

  ["COMIC_2_3_KR2"] = "Đây là vùng an toàn!",

  ["COMIC_2_3_KR3"] = "Nhìn! Một ngôi đền!",

  ["COMIC_2_3_KR5"] = "Vez'nan?!",

  ["COMIC_2_3_KR6_KR6"] = "TÔI ĐẾN TỪ TƯƠNG LAI Ở NÀO VEZ'NAN, KHÔNG TỪ KHI PHÁ HỦY VIÊN ĐÁ BỊ HỖN HỢP, BẮT ĐẦU SỬ DỤNG SỨC MẠNH CỦA NÓ, NHẬN TAY CỦA MÌNH HƠN MỘT LẦN...",

  ["COMIC_2_4_1_KR3"] = "Những rune druid này sẽ bảo vệ khu vực.",

  ["COMIC_2_4_2_KR3"] = "Đợi một chút…",

  ["COMIC_2_4_KR6_KR6"] = "...Rốt cuộc đã HOÀN TOÀN THA HÓA, GÂY THẢI BẠI CHO TOÀN VƯƠNG QUỐC BẤT CỨ NỖ LỰC CỦA CHÚNG TÔI.",

  ["COMIC_2_4a_KR5"] = "Giờ bình tĩnh nào... tôi đến để cầu hôn...",

  ["COMIC_2_4b_KR5"] = "...một thỏa thuận.",

  ["COMIC_2_5_KR3"] = "Đây không phải là rune druid… chúng là…",

  ["COMIC_2_5_KR5"] = "Sau những gì ngươi đã làm với vương quốc của chúng ta?!",

  ["COMIC_2_5_KR6_KR6"] = "NGAY CẢ CON TRAI CỦA BẠN, KING DENAS, KHÔNG SỐNG SÓT SAU CUỘC BIẾN NGHĨA CỦA MÌNH.",

  ["COMIC_2_6_KR3"] = "Chạng vạng\nELVES!",

  ["COMIC_2_6_KR5"] = "Đôi mắt của Vua Denas cần được mở ra.",

  ["COMIC_2_6_KR6_KR6"] = "VÀ VẬY, TÔI ĐƯỢC SẮP ĐẾN ĐỂ NGĂN CHẶN THIỆT VỜI NÀY.",

  ["COMIC_2_7_KR5"] = "Anh ta từ chối nhìn thấy mối nguy hiểm đang xâm chiếm vương quốc.",

  ["COMIC_2_7_KR6_KR6"] = "HMMM... TÔI SẼ KHÔNG TIN NHỮNG CÂU CHUYỆN ĐÓ DỄ DÀNG, NHƯNG...",

  ["COMIC_2_8_1_KR5"] = "Nhưng hãy để chúng tôi tìm vua của bạn...",

  ["COMIC_2_8_2_KR5"] = "...và chấm dứt mối đe dọa này.",

  ["COMIC_2_8_KR6_KR6"] = "...Rốt cuộc BẠN LÀ NGƯỜI TÌM KIẾM ĐÈN.",

  ["COMIC_2_8b_KR5"] = "...cùng nhau.",

  ["COMIC_2_9_KR6_KR6"] = "NGAY BÂY GIỜ, HÃY LẤY TUYỆT VỜI NÀY.",

  ["COMIC_3_1_KR2"] = "Nơi này khiến tôi rùng mình",

  ["COMIC_3_1_KR3"] = "Yêu tinh theo Malicia vào Di tích cổ của thành phố yêu tinh đầu tiên…",

  ["COMIC_3_1_KR5"] = "Ôi trời! Chúng ta có gì ở đây...?",

  ["COMIC_3_1_KR6_KR6"] = "SAU ĐÊM ĐÓ",

  ["COMIC_3_2_1_KR3"] = "Tôi sẽ trả thù!",

  ["COMIC_3_2_2_KR3"] = "Im đi... em yêu!",

  ["COMIC_3_2_KR2"] = "Thuốc súng và sắt! Chúng tôi có mọi thứ cần thiết để hạ gục kẻ địch!",

  ["COMIC_3_2_KR5"] = "Thanh kiếm hùng mạnh của Elynie!",

  ["COMIC_3_2_KR6_KR6"] = "DI CHUYỂN, ĐI YẾU!",

  ["COMIC_3_3_KR2"] = "Nếu bạn nói vậy...",

  ["COMIC_3_3_KR3"] = "Cố lên! Hãy bắt cô ấy ngay bây giờ!",

  ["COMIC_3_3_KR5"] = "Ôi!",

  ["COMIC_3_3_KR6_KR6"] = "ĐẤT NÀY HIỆN NAY DÀNH CHO ORCS!",

  ["COMIC_3_4_KR6_KR6"] = "HÃY XEM BẠN THỬ, GREENSKIN!",

  ["COMIC_3_4a_KR5"] = "Tất nhiên rồi...",

  ["COMIC_3_4b_KR5"] = "Đừng lãng phí thời gian nữa!",

  ["COMIC_3_5_1_KR3"] = "Của nó…",

  ["COMIC_3_5_2_KR3"] = "… một cái bẫy!",

  ["COMIC_3_5_KR6_KR6"] = "BẬC THẦY!",

  ["COMIC_3_5a_KR5"] = "À... nhưng anh ấy ở gần hơn bạn nghĩ.",

  ["COMIC_3_5b_KR5"] = "Vua của chúng ta vẫn đang mất tích.",

  ["COMIC_3_6_1_KR3"] = "Các bạn... chúng ta có bạn đồng hành.",

  ["COMIC_3_6_2_KR3"] = "Thực vậy!",

  ["COMIC_3_6_KR5"] = "Tuy nhiên, đây có thể là một trận chiến khó khăn.",

  ["COMIC_3_6_KR6_KR6"] = "KHÔNG CẦN PHẢI CHIẾN ĐẤU NHỮNG BẠN CỦA TÔI.",

  ["COMIC_3_7_KR3"] = "Đây là Thánh địa bóng tối của chúng tôi bây giờ!",

