  ["ENEMY_BOSS_BOLGUR_ENCYC_DESCRIPTION"] = "Vua của người lùn. Với khối tài sản khổng lồ và trí tuệ phi thường, ông trở thành ứng cử viên thích hợp cho ngôi vị thống trị. Anh ta cũng lái một chiếc máy khổng lồ.",

  ["ENEMY_BOSS_BOLGUR_ENCYC_NAME"] = "Golden King Bogul",

  ["ENEMY_BOSS_BOLGUR_ENCYC_SPECIAL"] = "Boss, tấn công tầm xa",

  ["ENEMY_BOSS_BRAM_DESCRIPTION"] = "Thủ lĩnh tàn bạo của loài Yêu tinh, Anh ta thích chặt đầu để hoàn thành công việc.",

  ["ENEMY_BOSS_BRAM_NAME"] = "Bram, the Beheader",

  ["ENEMY_BOSS_BRAM_SPECIAL"] = "*Trùm",

  ["ENEMY_BOSS_BULL_KING_DESCRIPTION"] = "Trong những năm đầu của mình, Bull Demon King đã tuyên thệ với sáu vị vua quỷ bao gồm Sun Wukong ở núi Huaguo, và tự gọi mình là \"Nhà hiền triết vĩ đại của Pingtian\". Sau đó, ông kết hôn với Công chúa Thiết Phiến ở phương Tây, kết hôn với Công chúa Ngọc Mặt và sống trong Động Moyun của Công chúa Ngọc Mặt một thời gian dài. Anh ta điều khiển quân đội bằng nắm đấm sắt và tàn nhẫn, anh ta là một anh hùng đã có mặt trên chiến trường trong một thời gian dài. Cơn giận Ngài xẻ núi non, và quyền năng Ngài san phẳng bầu trời.",

  ["ENEMY_BOSS_BULL_KING_NAME"] = "Bull Demon King",

  ["ENEMY_BOSS_CORRUPTED_DENAS_DESCRIPTION"] = "Vị vua thất bại của Linivia đã bị biến thành một kẻ ghê tởm cao ngất ngưởng bởi sức mạnh đen tối của những kẻ sùng bái All-Seeing Eye.",

  ["ENEMY_BOSS_CORRUPTED_DENAS_NAME"] = "Corrupted Denas",

  ["ENEMY_BOSS_CROCS_2_NAME"] = "Abominor Venomus",

  ["ENEMY_BOSS_CROCS_3_NAME"] = "Abominor Ignis",

  ["ENEMY_BOSS_CROCS_DESCRIPTION"] = "Hiện thân của cơn đói, nếu để sinh vật cổ xưa này ra tay, toàn bộ thế giới sẽ bị hắn nuốt chửng.",

  ["ENEMY_BOSS_CROCS_NAME"] = "Abominor",

  ["ENEMY_BOSS_CULT_LEADER_DESCRIPTION"] = "Tias chiếm giữ Tháp Hắc Ám. Với tư cách là thủ lĩnh hiện tại của giáo phái, anh ta đóng vai trò là cấp phó của con mắt độc ác nhìn thấu mọi thứ và lên kế hoạch xâm lược nhiều thế giới khác nhau.",

  ["ENEMY_BOSS_CULT_LEADER_NAME"] = "Seeress Mydrias",

  ["ENEMY_BOSS_DEFORMED_GRYMBEARD_NAME"] = "Deformed Grymbeard",

  ["ENEMY_BOSS_DRAGON_KING_ENCYC_DESCRIPTION"] = "Long Vương tỉnh dậy sau nhiều năm ngủ say, chỉ để tiêu diệt tất cả những ai cản đường hắn.",

  ["ENEMY_BOSS_DRAGON_KING_ENCYC_NAME"] = "Dragon King",

  ["ENEMY_BOSS_DRAGON_KING_ENCYC_SPECIAL"] = "Boss, không thể ngăn cản được",

  ["ENEMY_BOSS_DRAGON_STAGE_39_DESCRIPTION"] = "Con rồng mẹ mang đến sự thối nát, máu của nó đã xói mòn vùng đất và sinh ra vô số rồng để chiến đấu cho chủ nhân Tiranthor của nó.",

  ["ENEMY_BOSS_DRAGON_STAGE_39_NAME"] = "Mother of Dragonites",

  ["ENEMY_BOSS_DRAGON_STAGE_40_DESCRIPTION"] = "Bị thúc đẩy bởi tham vọng vô tận, con rồng độc ác này đã cố gắng chiếm lấy quyền lực hoàng gia của Vương quốc Cloud Realm. Anh ta là một kẻ chiếm đoạt tàn nhẫn và là một cỗ máy giết người không ngừng nghỉ. // Khi lượng máu vượt quá 1,1 lần, tháp pháo sẽ gây sát thương phần trăm cho quái vật thay vì sát thương cố định.",

  ["ENEMY_BOSS_DRAGON_STAGE_40_NAME"] = "Tiransol",

  ["ENEMY_BOSS_DROW_QUEEN_DESCRIPTION"] = "Nữ hoàng Chạng vạng độc ác và chết chóc. Ba lần chiến thắng trong cuộc thi sắc đẹp Malefic.",

  ["ENEMY_BOSS_DROW_QUEEN_NAME"] = "Malicia",

  ["ENEMY_BOSS_DROW_QUEEN_SPECIAL"] = "*Trùm",

  ["ENEMY_BOSS_DROW_QUEEN_ZEALOT_NAME"] = "Zealot",

  ["ENEMY_BOSS_DWARF_MECHA_NAME"] = "Golden King Bogul",

  ["ENEMY_BOSS_GNOLL_DESCRIPTION"] = "Kẻ ghê tởm và hôi hám nhất bộ tộc gnoll. Anh ấy tức giận vì không bao giờ được mời đến các bữa tiệc.",

  ["ENEMY_BOSS_GNOLL_NAME"] = "Hi-Hi Enha",

  ["ENEMY_BOSS_GNOLL_SPECIAL"] = "*Trùm",

  ["ENEMY_BOSS_GOBLIN_CHIEFTAIN_DESCRIPTION"] = "Thủ lĩnh Orc đáng sợ nhất. Năng lực chiến đấu của anh ấy chỉ phù hợp với những câu chuyện lửa trại cực kỳ nhàm chán của anh ấy.",

  ["ENEMY_BOSS_GOBLIN_CHIEFTAIN_EXTRA"] = "*Trùm",

  ["ENEMY_BOSS_GOBLIN_CHIEFTAIN_NAME"] = "Gul'Thak",

  ["ENEMY_BOSS_GOBLIN_CHIEFTAIN_SPECIAL"] = "*Trùm",

  ["ENEMY_BOSS_GREAT_T_ENCYC_DESCRIPTION"] = "Chúa tể số một, nguồn gốc của nỗi kinh hoàng trong thế giới đã mất, sự tàn ác và đói khát tuyệt đối... Nhưng anh ta thích ngủ hơn là thỏa mãn cơn thèm ăn, đó là một điều may mắn cho kẻ địch của anh ta.",

  ["ENEMY_BOSS_GREAT_T_ENCYC_NAME"] = "Big T",

  ["ENEMY_BOSS_GREAT_T_ENCYC_SPECIAL"] = "Boss, tấn công tầm xa, giết một đòn, hồi máu bằng cách ăn",

  ["ENEMY_BOSS_GRYMBEARD_DESCRIPTION"] = "Thủ lĩnh của lực lượng thép đen, Guixu.",

  ["ENEMY_BOSS_GRYMBEARD_NAME"] = "Grymbeard",

  ["ENEMY_BOSS_JOKULL_ENCYC_DESCRIPTION"] = "Mẹ rồng bay, lò núi. Cô ấy cực kỳ lớn và sức mạnh của cô ấy rất lớn.",

  ["ENEMY_BOSS_JOKULL_ENCYC_NAME"] = "Glacier Wyvern",

  ["ENEMY_BOSS_JOKULL_ENCYC_SPECIAL"] = "Trùm",

  ["ENEMY_BOSS_MACHINIST_DESCRIPTION"] = "Cưỡi trên phát minh mới nhất của mình, Trickwhisker truy đuổi kẻ địch của mình, trút mưa lửa và kim loại lên chúng.",

  ["ENEMY_BOSS_MACHINIST_NAME"] = "Grymbeard",

  ["ENEMY_BOSS_MURGLUM_DESCRIPTION"] = "Con rồng dung nham cái mạnh nhất từng được tạo ra. Trước đây, Mergulen bị Weznan điều khiển, nhưng giờ đây cô đã lấy lại được tự do và sẵn sàng đi theo chủ nhân mới của mình. Cô ấy là một thảm họa rực lửa mà cơn giận dữ gần như không thể dập tắt được.",

  ["ENEMY_BOSS_MURGLUM_EXTRA"] = "- Nhổ quả cầu lửa trên đường đi \n - Chặn tháp phòng thủ \n - Lao về phía đơn vị, gây sát thương khu vực",

  ["ENEMY_BOSS_MURGLUM_NAME"] = "Mercury",

  ["ENEMY_BOSS_NAVIRA_DESCRIPTION"] = "Bị ô nhiễm bởi sức mạnh cấm đoán và mất đi ân sủng của nữ thần, Fanriai cố gắng sử dụng ma thuật tử thần để xây dựng lại vinh quang cho yêu tinh.",

  ["ENEMY_BOSS_NAVIRA_NAME"] = "Navira",

  ["ENEMY_BOSS_OVERSEER_DESCRIPTION"] = "Con mắt toàn tri hay còn gọi là Con mắt của Chúa, Con mắt của Chúa quan phòng, Con mắt nhìn thấy mọi thứ, là một biểu tượng tôn giáo tượng trưng cho sự giám sát của Chúa đối với nhân loại. Những con thú ngoài hành tinh háu ăn trải rộng khắp các chiều không gian khác nhau, xâm chiếm các thế giới khác và hấp thụ năng lượng của chúng. Nó phải được ngăn chặn bằng mọi giá!",

  ["ENEMY_BOSS_OVERSEER_NAME"] = "The Overseer",

  ["ENEMY_BOSS_PIG_DESCRIPTION"] = "Kẻ tự xưng là Vua của các loài thú, đỉnh cao của mọi loài thú, có thể nghiền nát kẻ địch của mình bằng một cây đập lúa khổng lồ.",

  ["ENEMY_BOSS_PIG_NAME"] = "Goregrind",

  ["ENEMY_BOSS_POLYX_ENCYC_DESCRIPTION"] = "Người khôn ngoan nhất của Anuri. Bởi vì cơ thể quá lớn nên hắn chỉ có thể di chuyển nhờ vào sức mạnh ma thuật vô song của mình. Hãy cẩn thận đừng để bị anh ta nuốt chửng.",

  ["ENEMY_BOSS_POLYX_ENCYC_NAME"] = "Perix the Wise",

  ["ENEMY_BOSS_POLYX_ENCYC_SPECIAL"] = "Boss, giết ngay lập tức, dịch chuyển tức thời",

  ["ENEMY_BOSS_PRINCESS_IRON_FAN_CLONE_NAME"] = "Princess Iron Fan Clone",

  ["ENEMY_BOSS_PRINCESS_IRON_FAN_DESCRIPTION"] = "Bảo bối của Công chúa Quạt Sắt, Quạt Chuối, là bảo vật tinh thần do trời đất tạo ra. Một chiếc quạt sẽ dập tắt lửa, chiếc quạt thứ hai sẽ tạo ra gió và chiếc quạt thứ ba sẽ tạo ra mưa. Sau đó nó có thể gieo hạt và thu hoạch. Vì vậy, người dân tôn thờ cô như Tiên nữ quạt sắt, cứ mười năm lại cầu nguyện cho cô một lần và dâng vô số cống phẩm. Tướng mạo như ngọc ấm, tà khí như dao lạnh. Nếu bạn cưới vợ của quỷ vương, chiếc quạt thần của bạn cũng sẽ trở thành quỷ. Nó có thể dập tắt đám cháy đồng cỏ và tạo ra một làn sóng lớn.",

  ["ENEMY_BOSS_PRINCESS_IRON_FAN_NAME"] = "Princess Iron Fan",

  ["ENEMY_BOSS_REDBOY_TEEN_DESCRIPTION"] = "Là con trai của Bull Demon King và Iron Fan Princess, anh ta được biết đến với cái tên Holy Infant King. Red Boy từng tu luyện ở Flame Mountain trong ba trăm năm và luyện chế Samadhi Chân Hỏa. Sau đó, anh ta đến Núi Kim Cương để gây rắc rối và thường xuyên bắt nạt các vị thần đất và núi ở địa phương. Hoàng tử quỷ còn trẻ và phù phiếm. Anh ta có bản chất hung dữ và có lòng kiêu hãnh, tham vọng của anh ta ngày càng mạnh mẽ hơn. Anh ấy nói chuyện bằng lửa thật và chơi súng giỏi.",

  ["ENEMY_BOSS_REDBOY_TEEN_NAME"] = "Red Boy",

  ["ENEMY_BOSS_SPIDER_DEATH_TAUNT"] = "Điều này không thể được!!!",

  ["ENEMY_BOSS_SPIDER_DESCRIPTION"] = "Một điều kinh tởm... Đó là điều xảy ra khi bạn chơi với các tạo tác của yêu tinh.",

  ["ENEMY_BOSS_SPIDER_NAME"] = "Spider Goddess",

  ["ENEMY_BOSS_SPIDER_QUEEN_DESCRIPTION"] = "Nữ hoàng Nhện cổ đại, hiện thân của sức mạnh nguyên thủy, thức dậy sau giấc ngủ và thề sẽ lấy lại mọi thứ thuộc về mình.",

  ["ENEMY_BOSS_SPIDER_QUEEN_NAME"] = "Mygale",

  ["ENEMY_BOSS_SPIDER_SPECIAL"] = "*Trùm",

  ["ENEMY_BOSS_STAGE_08_DESCRIPTION"] = "Thủ lĩnh to lớn xấu xa của người da xanh, đủ mạnh để phá vỡ các bức tường pháo đài. Đối mặt với nguy cơ của riêng bạn.",

  ["ENEMY_BOSS_STAGE_08_EXTRA"] = "",

  ["ENEMY_BOSS_STAGE_08_NAME"] = "Gor’Thok",

  ["ENEMY_BOSS_STAGE_08_SPECIAL"] = "",

  ["ENEMY_BOSS_STAGE_10_DESCRIPTION"] = "Một cư dân ghê tởm của vùng núi mà chúng ta dường như đã vô tình đánh thức sau giấc ngủ ngắn.",

  ["ENEMY_BOSS_STAGE_10_EXTRA"] = "- Ăn các đơn vị\n- Đóng băng các tòa tháp gần đó",

  ["ENEMY_BOSS_STAGE_10_NAME"] = "J.T.",

  ["ENEMY_BOSS_STAGE_11_DESCRIPTION"] = "Nữ hoàng nhện của vùng đất phương Bắc và kẻ địch nguy hiểm, có khả năng tự mình san bằng toàn bộ khu trại.",

  ["ENEMY_BOSS_STAGE_11_EXTRA"] = "- Kháng phép cao\n- Ăn quân",

  ["ENEMY_BOSS_STAGE_11_NAME"] = "Sarelgaz",

  ["ENEMY_BOSS_STAGE_13_DESCRIPTION"] = "Vị vua troll hung hãn và oai nghiêm ghét ánh sáng mặt trời vô lý và muốn phá hủy Đền Stormcloud để các thầy Bruxa không thể khai thác sức mạnh của những viên ngọc mặt trời được nữa.",

  ["ENEMY_BOSS_STAGE_13_EXTRA"] = "- Giáp và kháng phép rất cao",

  ["ENEMY_BOSS_STAGE_13_NAME"] = "Moglok-Hai",

  ["ENEMY_BOSS_STAGE_15_DESCRIPTION"] = "Chúa tể Valardul đã thỏa thuận với thế lực bóng tối để cứu người dân của mình và giờ phải trả giá.",

  ["ENEMY_BOSS_STAGE_15_EXTRA"] = "- Giáp trung bình\n- Làm choáng các tòa tháp gần đó",

  ["ENEMY_BOSS_STAGE_15_NAME"] = "Lord Blackburn",

  ["ENEMY_BOSS_WINTER_QUEEN_ENCYC_DESCRIPTION"] = "Một sinh vật mạnh mẽ vừa thoát khỏi xiềng xích. Trong đầu cô lúc này chỉ có một điều duy nhất, đó là biến vương quốc này thành Nightmare băng giá cách xa hàng ngàn dặm.",

  ["ENEMY_BOSS_WINTER_QUEEN_ENCYC_NAME"] = "Winter Queen",

  ["ENEMY_BOSS_WINTER_QUEEN_ENCYC_SPECIAL"] = "Trùm",

  ["ENEMY_BOUNCER_DESCRIPTION"] = "Những tên côn đồ này là lính đánh thuê thấp thích cướp bóc.",

  ["ENEMY_BOUNCER_EXTRA"] = "- TỐC ĐỘ TRUNG BÌNH\n- THIỆT HẠI THẤP",

  ["ENEMY_BOUNCER_NAME"] = "Desert Thug",

  ["ENEMY_BRIGAND_DESCRIPTION"] = "Những kẻ ngoài vòng pháp luật được bọc thép có thể chịu được rất nhiều hình phạt.",

  ["ENEMY_BRIGAND_EXTRA"] = "- TỐC ĐỘ TRUNG BÌNH\n- GIÁP TRUNG BÌNH",

  ["ENEMY_BRIGAND_G6_DESCRIPTION"] = "Những chiến binh cứng cỏi rình mò khắp Valardul để cướp bóc những người vô tội.",

  ["ENEMY_BRIGAND_G6_EXTRA"] = "- Giáp hạng trung\n- Đòn đánh chảy máu",

  ["ENEMY_BRIGAND_G6_NAME"] = "Brigand",

  ["ENEMY_BRIGAND_NAME"] = "Brigand",

  ["ENEMY_BROODGUARD_DESCRIPTION"] = "Những chiến binh giống thằn lằn dũng cảm, vết thương của họ thúc đẩy cơn thịnh nộ chiến đấu của họ, khiến họ nhanh hơn.",

  ["ENEMY_BROODGUARD_EXTRA"] = "- ĐI NHANH HƠN KHI BỊ BỊ THƯƠNG",

  ["ENEMY_BROODGUARD_NAME"] = "Saurian Broodguard",

  ["ENEMY_BRUISER_EXTRA"] = "- sát thương thấp",

  ["ENEMY_BRUISER_LEGION_NAME"] = "Dwarf Legion",

  ["ENEMY_BRUISER_NAME"] = "Dwarf Guard",

  ["ENEMY_BRUISER_NOTIFICATION_DESCRIPTION"] = "Sống dưới lòng đất. Giỏi xẻ đôi kẻ địch bằng một chiếc rìu sắc bén.",

  ["ENEMY_BRUTE_DESCRIPTION"] = "Những loài bò sát giận dữ cao chót vót, không thể ngăn cản được trang bị roi năng lượng!",

  ["ENEMY_BRUTE_EXTRA"] = "- RẤT KHÓ\n- TẤN CÔNG KHU VỰC\n- TỐC ĐỘ CHẬM",

  ["ENEMY_BRUTE_NAME"] = "Saurian Brute",

  ["ENEMY_BRUTE_SPECIAL"] = "*Tấn công khu vực, Roi năng lượng mát mẻ",

  ["ENEMY_BRUTE_STORM_DESCRIPTION"] = "Demon Dragon Man cực kỳ cứng rắn có thể chịu được vô số đòn tấn công miễn là anh ta duy trì tư thế phòng thủ.",

  ["ENEMY_BRUTE_STORM_EXTRA"] = "- Vào trạng thái bất khả chiến bại và phục hồi máu",

  ["ENEMY_BRUTE_STORM_NAME"] = "Barbarian Pterosaur",

  ["ENEMY_BRUTE_WELDER_DESCRIPTION"] = "Những công nhân này sẽ sử dụng ngọn đuốc của họ vào kẻ địch một cách vô cớ.",

  ["ENEMY_BRUTE_WELDER_EXTRA"] = "- Chặn một tòa tháp khi bị giết",

  ["ENEMY_BRUTE_WELDER_NAME"] = "Brute Welder",

  ["ENEMY_BUCANEER_ENCYC_SPECIAL"] = "Các đòn tấn công tầm xa gây sát thương liên tục",

  ["ENEMY_BUCANEER_EXTRA"] = "- Tấn công tầm xa với sát thương liên tục",

  ["ENEMY_BUCANEER_NAME"] = "Pirate Sailor",

  ["ENEMY_BUCANEER_NOTIFICATION_DESCRIPTION"] = "Những kẻ xấu này thích rượu nhất nhưng chúng chỉ chia sẻ với người khác bằng cách châm lửa và ném đi.",

  ["ENEMY_BULLSHARK_DASHER_ENCYC_SPECIAL"] = "Hút máu khi bị cắn, bơi dưới lòng đất",

  ["ENEMY_BULLSHARK_DASHER_EXTRA"] = "- Ma cà rồng khi cắn trúng \n - Bơi dưới lòng đất",

  ["ENEMY_BULLSHARK_DASHER_NAME"] = "Dash Bull Shark",

  ["ENEMY_BULLSHARK_DASHER_NOTIFICATION_DESCRIPTION"] = "Những con thú nhanh nhẹn này là những tay bơi lội điêu luyện và thậm chí có thể bơi dưới lòng đất.",

  ["ENEMY_BURNING_TREANT_DESCRIPTION"] = "Những sinh vật bằng gỗ với mục đích xấu xa, sinh ra giữa một khu rừng đang cháy.",

  ["ENEMY_BURNING_TREANT_EXTRA"] = "- Sát thương diện tích\n- Để lại một vùng đất rực lửa khi tấn công",

  ["ENEMY_BURNING_TREANT_NAME"] = "Burning Treant",

  ["ENEMY_CAMEL_RIDER_ENCYC_SPECIAL"] = "Nhanh chóng, sinh ra lính lê dương khi lạc đà chết",

  ["ENEMY_CAMEL_RIDER_EXTRA"] = "- \n nhanh chóng - Sinh ra một quân đoàn khi một con lạc đà chết",

  ["ENEMY_CAMEL_RIDER_NAME"] = "Camel Rider",

