  ["ENEMY_CORSAIR_NAME"] = "Pirate Leader",

  ["ENEMY_CORSAIR_NOTIFICATION_DESCRIPTION"] = "Những chiến binh dũng cảm, vui vẻ chiến đấu và cướp bóc cho người chủ của mình, người phải trả giá cao nhất!",

  ["ENEMY_CROCS_BASIC_DESCRIPTION"] = "Một chiến binh Crok kiêu hãnh, vẫn còn non trẻ và chỉ còn vài calo nữa là có thể biến thành cỗ máy giết chóc mà nó biết là có thể.",

  ["ENEMY_CROCS_BASIC_EGG_DESCRIPTION"] = "Mới sinh ra và không thể ngăn cản trên đôi chân của mình, \"chúng phát triển quá nhanh\" là một cụm từ được phát minh ra nhờ những đứa trẻ đầy bất ngờ này.",

  ["ENEMY_CROCS_BASIC_EGG_EXTRA"] = "- Không thể chặn\n- Giáp thấp\n- Nở thành Gator sau vài giây",

  ["ENEMY_CROCS_BASIC_EGG_NAME"] = "Crokinder",

  ["ENEMY_CROCS_BASIC_EXTRA"] = "- Cận chiến",

  ["ENEMY_CROCS_BASIC_NAME"] = "Gator",

  ["ENEMY_CROCS_EGG_SPAWNER_DESCRIPTION"] = "Tên lừa đảo này đang gây ra rất nhiều rắc rối! Cứ sau vài bước, cô ấy lại thả những quả trứng nở thành những con cá sấu điên cuồng— một vườn ươm di động với một vết cắn nghiêm trọng!",

  ["ENEMY_CROCS_EGG_SPAWNER_EXTRA"] = "- Sinh ra Crokinders trên Path\n- Giáp trung bình",

  ["ENEMY_CROCS_EGG_SPAWNER_NAME"] = "Nesting Gator",

  ["ENEMY_CROCS_FLIER_DESCRIPTION"] = "Những Croks xảo quyệt, khinh miệt sự tiến hóa tự nhiên, đã rèn luyện đôi cánh của chính mình để giành được lợi thế trên không.",

  ["ENEMY_CROCS_FLIER_EXTRA"] = "- Bay",

  ["ENEMY_CROCS_FLIER_NAME"] = "Winged Crok",

  ["ENEMY_CROCS_HYDRA_DESCRIPTION"] = "Hai cái đầu tốt hơn một, và Hydra đã chứng minh điều đó. Có một truyền thuyết xa xưa về quái vật ba đầu như thế này, nhưng có lẽ đó là lời nói dối.",

  ["ENEMY_CROCS_HYDRA_EXTRA"] = "- Sinh ra cái đầu thứ ba khi chết\n- Phun chất độc xuống đất\n- Kháng phép cao",

  ["ENEMY_CROCS_HYDRA_NAME"] = "Hydra",

  ["ENEMY_CROCS_QUICKFEET_GATOR_NAME"] = "Quickfeet",

  ["ENEMY_CROCS_RANGED_DESCRIPTION"] = "Những thợ săn thằn lằn tốc độ có thể đối phó với kẻ địch bằng súng cao su tầm xa.",

  ["ENEMY_CROCS_RANGED_EXTRA"] = "- Fast\n- Tầm xa",

  ["ENEMY_CROCS_RANGED_NAME"] = "Lizardshot",

  ["ENEMY_CROCS_SHAMAN_DESCRIPTION"] = "Những sinh vật ma thuật có tầm quan trọng lớn đối với người Croks. Suy cho cùng, đối với một chủng tộc máu lạnh, khả năng nhìn trước được vận mệnh của bầu trời là vấn đề sinh tử.",

  ["ENEMY_CROCS_SHAMAN_EXTRA"] = "- Sát thương phép tầm xa\n- Kháng phép trung bình\n- Chữa lành vết thương cho cá sấu khác\n- Tháp choáng",

  ["ENEMY_CROCS_SHAMAN_NAME"] = "Wise Crok",

  ["ENEMY_CROCS_TANK_DESCRIPTION"] = "Nền tảng của lực lượng Croks, họ coi \"phòng thủ tốt là cách tấn công tốt nhất\", sử dụng đạn pháo đánh cắp được theo cách họ thấy phù hợp.",

  ["ENEMY_CROCS_TANK_EXTRA"] = "- Máu cao\n- Giáp trung bình\n- Quay khi bị chặn",

  ["ENEMY_CROCS_TANK_NAME"] = "Tankzard",

  ["ENEMY_CROWCALLER_DESCRIPTION"] = "Những pháp sư bóng tối này kêu gọi những con quạ đen nhất để do thám phòng tuyến của kẻ địch.",

  ["ENEMY_CROWCALLER_EXTRA"] = "- Kháng phép trung bình\n- Triệu hồi quạ định kỳ",

  ["ENEMY_CROWCALLER_NAME"] = "Crowcaller",

  ["ENEMY_CROWCALLER_SPECIAL"] = "",

  ["ENEMY_CROW_DESCRIPTION"] = "Lông vũ màu đen và nhiều điềm xấu bay qua đầu quân lính, tốt hơn hết hãy tiêu diệt chúng.",

  ["ENEMY_CROW_EXTRA"] = "- Bay",

  ["ENEMY_CROW_NAME"] = "Crow",

  ["ENEMY_CROW_SPECIAL"] = "",

  ["ENEMY_CRYSTAL_AMPHIPTERE_ENCYC_SPECIAL"] = "Sau khi tiêm ma thuật, tốc độ tăng mạnh và đơn vị bay",

  ["ENEMY_CRYSTAL_AMPHIPTERE_EXTRA"] = "- Sau khi tiêm ma thuật, tốc độ tăng mạnh \n-Đơn vị bay",

  ["ENEMY_CRYSTAL_AMPHIPTERE_NAME"] = "Crystal Winged Serpent",

  ["ENEMY_CRYSTAL_AMPHIPTERE_NOTIFICATION_DESCRIPTION"] = "Con rồng tiến hóa có thể hợp nhất với các tinh thể. Nó dễ bị ảnh hưởng bởi ma thuật và có thể sử dụng năng lượng ma thuật để đạt tốc độ tối đa khi bay.",

  ["ENEMY_CRYSTAL_DEMOLISHER_ENCYC_SPECIAL"] = "Giáp có thể được tăng lên khi ở gần nhà ngoại cảm và sẽ gây sát thương diện tích khi chết.",

  ["ENEMY_CRYSTAL_DEMOLISHER_EXTRA"] = "- Có thể tăng giáp khi ở gần \n tâm linh - Sát thương diện rộng sẽ gây ra khi chết \n - Tốc độ rất chậm",

  ["ENEMY_CRYSTAL_DEMOLISHER_NAME"] = "Crystal Destroyer",

  ["ENEMY_CRYSTAL_DEMOLISHER_NOTIFICATION_DESCRIPTION"] = "Một con rối có toàn bộ cơ thể được làm từ tinh thể ma thuật. Một khi đã tập hợp đủ sức mạnh ma thuật, nó có thể phá hủy thế giới và trở nên không thể ngăn cản dù nó đi đến đâu.",

  ["ENEMY_CRYSTAL_GOLEM_DESCRIPTION"] = "Được thấm nhuần phép thuật siêu nhiên từ các tinh thể của nó, những hình nộm bằng đá này gần như không thể ngăn cản được.",

  ["ENEMY_CRYSTAL_GOLEM_EXTRA"] = "- Mini-boss\n- Giáp cao",

