  ["HERO_DRAGON_ARB_TOWER RUNES_DESCRIPTION_3"] = "Tăng sát thương của các tòa tháp gần đó lên %$heroes.hero_dragon_arb.tower_runes.s_damage_factor[3]%$% trong %$heroes.hero_dragon_arb.tower_runes.duration[3]%$ giây.",

