  ["HERO_ONI_G6_SKILL_A_1_DESCRIPTION"] = "Truyền sức mạnh của mình để hạ gục một kẻ địch, gây sát thương chuẩn {b.heroes.hero_oni.skill_a.damage_min}-{b.heroes.hero_oni.skill_a.damage_max}.",

  ["HERO_ONI_G6_SKILL_A_1_TITLE"] = "DEATH STRIKE I",

  ["HERO_ONI_G6_SKILL_A_2_DESCRIPTION"] = "Truyền sức mạnh của mình để hạ gục một kẻ địch, gây sát thương chuẩn {b.heroes.hero_oni.upgrades.upg_sa1.damage_min}-{b.heroes.hero_oni.upgrades.upg_sa1.damage_max}.",

