  ["HERO_ONI_G6_SKILL_A_3_DESCRIPTION"] = "Truyền sức mạnh của mình để hạ gục một kẻ địch, gây sát thương chuẩn {b.heroes.hero_oni.upgrades.upg_sa2.damage_min}-{b.heroes.hero_oni.upgrades.upg_sa2.damage_max}.",

  ["HERO_ONI_G6_SKILL_A_3_TITLE"] = "DEATH STRIKE III",

  ["HERO_ONI_G6_SKILL_B_1_DESCRIPTION"] = "Khi HP thấp hơn {b.heroes.hero_oni.skill_b.trigger_threshold}%, Chiến binh ma có thể chuyển sang thế phòng thủ và hồi phục {b.heroes.hero_oni.skill_b.heal_ptg}% HP trong vòng {b.heroes.hero_oni.skill_b.s_duration} giây.",

  ["HERO_ONI_G6_SKILL_B_1_TITLE"] = "NETHERFOCUS I",

  ["HERO_ONI_G6_SKILL_B_2_DESCRIPTION"] = "Khi lượng máu còn dưới {b.heroes.hero_oni.skill_b.trigger_threshold}%, Chiến binh ma có thể chuyển sang thế phòng thủ và hồi phục {b.heroes.hero_oni.upgrades.upg_sb1.heal_ptg}% máu của mình trong vòng {b.heroes.hero_oni.skill_b.s_duration} giây.",

  ["HERO_ONI_G6_SKILL_B_2_TITLE"] = "NETHERFOCUS II",

  ["HERO_ONI_G6_SKILL_B_3_DESCRIPTION"] = "Khi lượng máu còn dưới {b.heroes.hero_oni.skill_b.trigger_threshold}%, Chiến binh ma có thể chuyển sang thế phòng thủ và hồi phục {b.heroes.hero_oni.upgrades.upg_sb2.heal_ptg}% máu của mình trong vòng {b.heroes.hero_oni.skill_b.s_duration} giây.",

  ["HERO_ONI_G6_SKILL_B_3_TITLE"] = "NETHERFOCUS III",

  ["HERO_ONI_G6_SKILL_C_1_DESCRIPTION"] = "Dịch chuyển đến cạnh kẻ địch đứng đầu gần đó và chém nó ba lần. Mỗi đòn đánh gây sát thương vật lý {b.heroes.hero_oni.skill_c.damage_min[1]}-{b.heroes.hero_oni.skill_c.damage_max[1]} và giảm vĩnh viễn {b.heroes.hero_oni.skill_c.armor_red}% giáp của kẻ địch.",

  ["HERO_ONI_G6_SKILL_C_1_TITLE"] = "HELLISH BLINK I",

  ["HERO_ONI_G6_SKILL_C_2_DESCRIPTION"] = "Dịch chuyển đến cạnh kẻ địch đứng đầu gần đó và chém nó ba lần. Mỗi đòn đánh gây sát thương vật lý {b.heroes.hero_oni.upgrades.upg_sc1.damage_min[2]}-{b.heroes.hero_oni.upgrades.upg_sc1.damage_max[2]} và giảm vĩnh viễn {b.heroes.hero_oni.upgrades.upg_sc1.armor_red}% giáp của kẻ địch.",

  ["HERO_ONI_G6_SKILL_C_2_TITLE"] = "HELLISH BLINK II",

  ["HERO_ONI_G6_SKILL_C_3_DESCRIPTION"] = "Dịch chuyển đến cạnh kẻ địch đứng đầu gần đó và chém nó ba lần. Mỗi đòn đánh gây sát thương vật lý {b.heroes.hero_oni.upgrades.upg_sc1.damage_min[3]}-{b.heroes.hero_oni.upgrades.upg_sc2.damage_max[3]} và giảm vĩnh viễn {b.heroes.hero_oni.upgrades.upg_sc2.armor_red}% giáp của kẻ địch.",

  ["HERO_ONI_G6_SKILL_C_3_TITLE"] = "HELLISH BLINK III",

  ["HERO_ONI_G6_TALENT_1_DESCRIPTION"] = "Sau khi sử dụng một kỹ năng, đòn tấn công cơ bản tiếp theo của Oni gây thêm {b.heroes.hero_oni.talent_1.s_damage_factor}% sát thương.",

  ["HERO_ONI_G6_TALENT_1_TITLE"] = "LETHAL COMBO",

  ["HERO_ONI_G6_TALENT_2_DESCRIPTION"] = "Trong khi liên tục giao tranh với cùng một kẻ địch, các Anh hùng hồi phục máu bằng {b.heroes.hero_oni.talent_2.lifesteal}% sát thương tấn công gây ra.",

  ["HERO_ONI_G6_TALENT_2_TITLE"] = "DUEL FERVOR",

  ["HERO_ONI_G6_ULT_DESCRIPTION"] = "Đâm kiếm xuống đất, triệu hồi lưỡi kiếm của những người lính đã ngã xuống, gây sát thương chuẩn {b.heroes.hero_oni.ultimate.damage_min}-{b.heroes.hero_oni.ultimate.damage_max} cho kẻ địch trong một khu vực.",

