  ["HERO_PENUMBRA_ATTACKRATE"] = "Trung bình",

  ["HERO_PENUMBRA_BIO"] = "Một bóng ma của ác thần Umbra đã hiện hình và bay đi để gây ra sự hỗn loạn cho tất cả những ai nằm dưới cái bóng của hắn.",

  ["HERO_PENUMBRA_CLASS"] = "Rồng bóng tối",

  ["HERO_PENUMBRA_DESCRIPTION"] = "Một bóng ma của ác thần Umbra đã hiện hình và bay đi để gây ra sự hỗn loạn cho tất cả những ai nằm dưới cái bóng của hắn.",

