  ["HERO_PRIEST_HOLYLIGHT_DESCRIPTION_1"] = "Việc hồi máu ảnh hưởng đến tối đa 2 đồng minh, mỗi người hồi phục 25 mạng sống cho họ, với 10% cơ hội hồi sinh những người đã ngã xuống.",

  ["HERO_PRIEST_HOLYLIGHT_DESCRIPTION_2"] = "Hồi máu ảnh hưởng đến tối đa 3 đồng minh, mỗi người hồi phục 50 mạng sống cho họ, với 20% cơ hội hồi sinh những người đã ngã xuống",

  ["HERO_PRIEST_HOLYLIGHT_DESCRIPTION_3"] = "Việc hồi máu ảnh hưởng đến tối đa 4 đồng minh, mỗi người hồi phục 75 mạng sống cho họ, với 30% cơ hội hồi sinh những người đã ngã xuống.",

  ["HERO_PRIEST_HOLYLIGHT_TITLE"] = "Holy Light",

