  ["HERO_PRIEST_WINGSOFLIGHT_TITLE"] = "Wings of Light",

  ["HERO_RAELYN_ATTACKRATE"] = "Chậm",

  ["HERO_RAELYN_BRUTAL_SLASH_DESCRIPTION_1"] = "Dùng kiếm tấn công kẻ địch một cách tàn bạo, gây %$heroes.hero_raelyn.brutal_slash.s_damage[1]%$ sát thương chuẩn.",

  ["HERO_RAELYN_BRUTAL_SLASH_DESCRIPTION_2"] = "Dùng kiếm tấn công kẻ địch một cách tàn bạo, gây %$heroes.hero_raelyn.brutal_slash.s_damage[2]%$ sát thương chuẩn.",

