  ["HERO_RAELYN_COMMAND_ORDERS_DESCRIPTION_3"] = "Hiệp sĩ bóng đêm có máu %$heroes.hero_raelyn.ultimate.entity.hp_max[4]%$ và gây sát thương chuẩn %$heroes.hero_raelyn.ultimate.entity.damage_min[4]%$-%$heroes.hero_raelyn.ultimate.entity.damage_max[4]%$.",

  ["HERO_RAELYN_COMMAND_ORDERS_MENUBOTTOM_DESCRIPTION"] = "Triệu hồi một Hiệp sĩ bóng đêm đến chiến trường.",

  ["HERO_RAELYN_COMMAND_ORDERS_MENUBOTTOM_NAME"] = "Command Orders",

  ["HERO_RAELYN_COMMAND_ORDERS_TITLE"] = "COMMAND ORDERS",

  ["HERO_RAELYN_DESC"] = "Raelyn oai phong sống để lãnh đạo các Hiệp sĩ bóng đêm ở đội tiên phong. Sự tàn bạo và không ngừng nghỉ của cô đã khiến Vez'nan công nhận cô và khiến người Linirean sợ hãi. Luôn sẵn sàng cho một cuộc chiến tốt đẹp, cô là người tình nguyện đầu tiên gia nhập hàng ngũ của Phù thủy Hắc ám.",

  ["HERO_RAELYN_INSPIRE_FEAR_DESCRIPTION_1"] = "Làm choáng kẻ địch ở gần trong %$heroes.hero_raelyn.inspire_fear.stun_duration[1]%$ giây và giảm sát thương tấn công của chúng đi %$heroes.hero_raelyn.inspire_fear.s_inflicted_damage_factor[1]%$% trong %$heroes.hero_raelyn.inspire_fear.damage_duration[1]%$ giây.",

  ["HERO_RAELYN_INSPIRE_FEAR_DESCRIPTION_2"] = "Làm choáng kẻ địch ở gần trong %$heroes.hero_raelyn.inspire_fear.stun_duration[2]%$ giây và giảm sát thương tấn công của chúng đi %$heroes.hero_raelyn.inspire_fear.s_inflicted_damage_factor[2]%$% trong %$heroes.hero_raelyn.inspire_fear.damage_duration[2]%$ giây.",

  ["HERO_RAELYN_INSPIRE_FEAR_DESCRIPTION_3"] = "Làm choáng kẻ địch ở gần trong %$heroes.hero_raelyn.inspire_fear.stun_duration[3]%$ giây và giảm sát thương tấn công của chúng đi %$heroes.hero_raelyn.inspire_fear.s_inflicted_damage_factor[3]%$% trong %$heroes.hero_raelyn.inspire_fear.damage_duration[3]%$ giây.",

  ["HERO_RAELYN_INSPIRE_FEAR_TITLE"] = "INSPIRE FEAR",

  ["HERO_RAELYN_NAME"] = "Raelyn",

  ["HERO_RAELYN_ONSLAUGHT_DESCRIPTION_1"] = "Trong %$heroes.hero_raelyn.onslaught.duration[1]%$ giây, Raelyn tấn công nhanh hơn và gây %$heroes.hero_raelyn.onslaught.damage_factor[1]%$% sát thương tấn công của cô ấy trong một khu vực nhỏ xung quanh mục tiêu chính.",

