  ["TIP!"] = "MẸO!",

  ["TIP_1"] = "Chạm vào kẻ địch sẽ hiển thị cho bạn số liệu thống kê hiện tại của nó.",

  ["TIP_10"] = "Vụ nổ của tảng đá có thể gây sát thương cho kẻ địch đang bay mặc dù chúng không thể nhắm mục tiêu trực tiếp vào chúng.",

  ["TIP_10_TITLE"] = "Kẻ địch bay",

  ["TIP_11"] = "Điều chỉnh điểm tập hợp của binh lính để tạo ra chiến lược tốt hơn.",

  ["TIP_11_NAME"] = "cú sốc tâm hồn",

  ["TIP_12"] = "Gọi một đợt sớm sẽ mang lại tiền thưởng vàng và giảm thời gian hồi chiêu của phép thuật.",

  ["TIP_12_NAME"] = "Đạo cụ mạnh mẽ",

  ["TIP_13"] = "Bạn có thể kiểm tra kẻ địch của đợt đang đến bằng cách nhấn vào biểu tượng đợt một lần.",

  ["TIP_14"] = "Sử dụng quân tiếp viện hoặc doanh trại để cô lập kẻ địch rắc rối.",

  ["TIP_15"] = "Bản nâng cấp Ancient Oak Spear của Forest Keepers gây sát thương chuẩn cho kẻ địch.",

  ["TIP_16"] = "Sức mạnh đặc biệt của anh hùng có thời gian hồi chiêu đa dạng. Hãy chắc chắn để tìm hiểu anh hùng của bạn.",

  ["TIP_17"] = "Tất cả các loài nhện đều có khả năng kháng Độc.",

  ["TIP_18"] = "Hãy cẩn thận với những chú thỏ: những kẻ địch lông xù này quá dễ thương để bị binh lính chặn lại.",

  ["TIP_19"] = "Ngay cả khi tháp doanh trại bị vô hiệu hóa, binh lính của nó sẽ tiếp tục chiến đấu và ngăn chặn kẻ địch.",

  ["TIP_1_NAME"] = "thông tin kẻ địch",

  ["TIP_2"] = "Doanh trại cấp 2 và 3 có khả năng tấn công tầm xa có khả năng nhắm mục tiêu vào kẻ địch đang bay.",

  ["TIP_20"] = "Hãy chú ý đến những điều đặc biệt trên sân khấu, đôi khi việc xây dựng chiến lược xung quanh chúng thật đáng giá và thú vị!",

  ["TIP_21"] = "Tối đa hóa khả năng sát thương của Druid bằng cách đặt doanh trại gần chúng.",

  ["TIP_22"] = "Tất cả các tác dụng chữa bệnh cũng loại bỏ chất độc và bệnh tật.",

  ["TIP_23"] = "Mỗi anh hùng đều có những khả năng riêng biệt cho phép thực hiện các chiến lược khác nhau.",

  ["TIP_24"] = "Gọi một đợt sớm hơn không làm giảm thời gian hồi chiêu của các kỹ năng của tháp.",

  ["TIP_25"] = "Đôi khi, việc tiết kiệm một ít vàng để thích ứng với những kẻ địch bất ngờ là điều khôn ngoan.",

  ["TIP_26"] = "Những kẻ man rợ tự chữa lành vết thương và trở nên mạnh mẽ hơn mỗi khi ăn.",

  ["TIP_27"] = "Bóng ma cát không thể nâng quan tài lên khi bị chặn.",

  ["TIP_28"] = "Chất độc từ kẻ địch không gây chết người. Rút lui những người lính bị đầu độc của bạn để cứu họ.",

  ["TIP_29"] = "Kẻ hành quyết không thể xử tử anh hùng.",

  ["TIP_2_NAME"] = "Sát thương phép",

  ["TIP_3"] = "Kẻ địch và binh lính mặc giáp nhận ít sát thương vật lý hơn.",

  ["TIP_30"] = "Hào quang Shaman kết hợp có thể khiến Savage gần như bất khả chiến bại.",

  ["TIP_31"] = "Đôi khi việc bán tháp phòng thủ mà bạn hiện không sử dụng có thể giúp bạn có đủ tiền để vượt qua những tình huống căng thẳng.",

  ["TIP_32"] = "So với việc xây dựng nhiều tháp phòng thủ cùng cấp, việc nâng cấp tháp phòng thủ thường đạt kết quả tốt hơn.",

  ["TIP_33"] = "Kẻ địch bay không bị chặn và hầu hết các tháp pháo sẽ không bắn vào chúng.",

  ["TIP_34"] = "Bạn có thể sử dụng các đạo cụ mạnh mẽ trong cửa hàng để giúp bạn chiến đấu. Họ có thể giúp lật ngược tình thế của toàn bộ trận chiến!",

  ["TIP_35"] = "Kẻ địch và binh lính bọc thép chịu ít sát thương vật lý hơn.",

  ["TIP_36"] = "Hỗ trợ doanh trại bằng các cuộc tấn công tầm xa để tối đa hóa khả năng tiếp xúc của kẻ địch.",

  ["TIP_37"] = "Quân tiếp viện là một cách tuyệt vời để phân chia lực lượng của kẻ địch.",

  ["TIP_38"] = "Pháo binh có hiệu quả nhất khi chống lại kẻ địch đông đúc.",

  ["TIP_39"] = "Tâm vụ nổ pháo gây sát thương cao nhất.",

  ["TIP_3_NAME"] = "Nâng cấp doanh trại",

